<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowUpRight, Boxes, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Download, FileSpreadsheet, FolderOpen, LayoutDashboard, LogOut, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, UploadCloud, X } from 'lucide-vue-next'
import { api, date, fields, hasRole, key, labels, loadMemberships, post, put, restore, session } from './api'
import ImportWizard from './ImportWizard.vue'
import Workbench from './Workbench.vue'
import StrategyLab from './StrategyLab.vue'
import OperationsPanel from './OperationsPanel.vue'
import EnterpriseHub from './EnterpriseHub.vue'
const enterpriseBatch=ref('')

const nav = ref('tasks'), booting = ref(true), busy = ref(false)
const email = ref('operator@demo.local'), password = ref('Demo2026!match')
const runs = ref<any[]>([]), dashboard = ref<any>({}), catalogs = ref<any[]>([]), exports = ref<any[]>([]), members = ref<any[]>([]), policies = ref<any[]>([]), audits = ref<any[]>([]), settings = ref<any>({}), batches = ref<any[]>([])
const catalogCursor=ref<string|null>(null),batchCursor=ref<string|null>(null),memberCursor=ref<string|null>(null),auditCursor=ref<string|null>(null),catalogQuery=ref(''),batchQuery=ref(''),memberQuery=ref('')
const runCursor=ref<string|null>(null), exportCursor=ref<string|null>(null)
const query=ref(''), status=ref(''), activeRun=ref<any>(null), importOpen=ref(false), importMode=ref('batch'), revisionBatch=ref(''), catalogParent=ref('')
const selectedCatalog=ref(''), products=ref<any[]>([]), productQuery=ref(''), productCursor=ref<string|null>(null)
const exportOpen=ref(false), exportRun=ref<any>(null), exportKind=ref('confirmed'), exportFormat=ref('xlsx'), includeRaw=ref(false)
const rerunOpen=ref(false), rerunBatch=ref(''), rerunRevision=ref(''), rerunCatalog=ref(''), rerunPolicy=ref('')
const memberOpen=ref(false), memberForm=ref({email:'',name:'',password:'',roles:['operator']})
const policyOpen=ref(false), policyForm=ref({name:'',engine:'rules',high_threshold:0.90,margin:0.08}), settingsTab=ref('members')
const titles:Record<string,string>={tasks:'匹配任务',catalog:'标准商品库',exports:'导出记录',settings:'组织设置',enterprise:'发布与协作',workbench:'匹配工作台'}
const orgName=computed(()=>session.memberships.find(x=>x.org_id===session.org)?.name||'')
const roles=computed(()=>session.memberships.find(x=>x.org_id===session.org)?.roles.map((r:string)=>labels[r]).join(' / '))
const totalRuns=computed(()=>Object.values(dashboard.value.runs||{}).reduce((a:any,b:any)=>a+b,0))
const pending=computed(()=>dashboard.value.decisions?.PENDING||0)
const published=computed(()=>catalogs.value.flatMap(c=>c.versions.filter((v:any)=>v.status==='PUBLISHED'&&(!c.active_version_id||v.id===c.active_version_id)).map((v:any)=>({...v,label:`${c.name} · v${v.number}`}))))
const rerunRevisions=computed(()=>batches.value.find(b=>b.id===rerunBatch.value)?.revisions||[])
const exportCount=computed(()=>exportKind.value==='confirmed'?(exportRun.value?.decisions?.CONFIRMED||0):(exportRun.value?.total||0))
const progress=(r:any)=>r.total?Math.round(r.processed/r.total*100):0
function error(e:any){ElMessage.error(e.message||'操作失败，请重试')}

async function login(){busy.value=true;try{const r=await post('/auth/login',{email:email.value,password:password.value});session.token=r.access_token;session.user=r.user;await loadMemberships();await load();}catch(e){error(e)}finally{busy.value=false}}
async function logout(){try{await post('/auth/logout')}catch{}session.token='';session.user=null;session.org='';nav.value='tasks';activeRun.value=null}
async function loadRuns(append=false){const r=await api('/runs?'+new URLSearchParams({...(query.value?{q:query.value}:{}),...(status.value?{status:status.value}:{}),...(append&&runCursor.value?{cursor:runCursor.value}:{})}));runs.value=append?[...runs.value,...r.items]:r.items;runCursor.value=r.next_cursor;runs.value.sort((a,b)=>b.created_at.localeCompare(a.created_at))}
async function load(){busy.value=true;try{const [d,c,p,b]=await Promise.all([api('/dashboard'),api('/catalogs'),api('/policies'),api('/batches')]);dashboard.value=d;catalogs.value=c.items;catalogCursor.value=c.next_cursor;policies.value=p.items;batches.value=b.items;batchCursor.value=b.next_cursor;await loadRuns();if(nav.value==='exports')await loadExports();if(nav.value==='settings')await loadSettings()}catch(e){error(e)}finally{busy.value=false}}
async function navigate(next:string){nav.value=next;try{if(next==='tasks')await load();if(next==='catalog'){await loadCatalogs();if(!selectedCatalog.value)selectedCatalog.value=published.value[0]?.id||'';await loadProducts()}if(next==='exports')await loadExports();if(next==='settings')await loadSettings()}catch(e){error(e)}}
async function openRun(r:any){try{activeRun.value={...await api('/runs/'+r.id),initial_item_id:r.item_id};nav.value='workbench'}catch(e){error(e)}}
function startImport(mode='batch',batch='',catalog=''){importMode.value=mode;revisionBatch.value=batch;catalogParent.value=catalog;importOpen.value=true}
async function imported(payload:any){importOpen.value=false;await load();if(payload.run_id)await openRun({id:payload.run_id});else await navigate(payload.catalog?'catalog':'tasks')}
async function loadProducts(append=false){if(!selectedCatalog.value){products.value=[];return}const r=await api(`/catalog-versions/${selectedCatalog.value}/products?`+new URLSearchParams({q:productQuery.value,...(append&&productCursor.value?{cursor:productCursor.value}:{})}));products.value=append?[...products.value,...r.items]:r.items;productCursor.value=r.next_cursor}
async function publish(v:any){try{await ElMessageBox.confirm(`发布标准库 v${v.number}，共 ${v.row_count} 件商品。发布后该版本内容将冻结。`,'发布标准库',{confirmButtonText:'确认发布',cancelButtonText:'取消'});await post(`/catalog-versions/${v.id}/publish`,{expected_version:v.lock_version});ElMessage.success('标准库版本已发布');await load();await navigate('catalog')}catch(e:any){if(e!=='cancel'&&e!=='close')error(e)}}
async function loadExports(append=false){const r=await api('/exports'+(append&&exportCursor.value?'?cursor='+exportCursor.value:''));exports.value=append?[...exports.value,...r.items]:r.items;exportCursor.value=r.next_cursor;exports.value.sort((a,b)=>b.created_at.localeCompare(a.created_at))}
function showExport(r:any){exportRun.value=r;exportKind.value='confirmed';exportOpen.value=true}
async function createExport(){busy.value=true;try{const r=await post(`/runs/${exportRun.value.id}/exports`,{kind:exportKind.value,format:exportFormat.value,include_raw:includeRaw.value},key());exportOpen.value=false;ElMessage.success(`已冻结 ${r.count} 条记录，正在生成文件`);await navigate('exports')}catch(e){error(e)}finally{busy.value=false}}
async function download(e:any){try{const blob=await api(`/exports/${e.id}/download`);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`商品匹配_${e.id.slice(0,8)}.${e.format}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){error(e)}}
async function cancelRun(r:any){try{const {value}=await ElMessageBox.prompt('取消后保留诊断结果，该运行不开放审核和正式导出。','取消任务',{inputPlaceholder:'请填写取消原因',inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'取消任务',cancelButtonText:'返回'});await post(`/runs/${r.id}/cancel`,{reason:value});await loadRuns()}catch(e:any){if(e!=='cancel'&&e!=='close')error(e)}}
async function retryRun(r:any){try{const result=await post(`/runs/${r.id}/retry`,{},key());ElMessage.success('已创建独立重试运行');await load();await openRun(result)}catch(e){error(e)}}
async function showRerun(){await load();rerunBatch.value=batches.value[0]?.id||'';rerunRevision.value=rerunRevisions.value[0]?.id||'';rerunCatalog.value=published.value[0]?.id||'';rerunPolicy.value=policies.value[0]?.id||'';rerunOpen.value=true}
async function submitRerun(){busy.value=true;try{const r=await post('/runs',{revision_id:rerunRevision.value,catalog_version_id:rerunCatalog.value,policy_id:rerunPolicy.value},key());rerunOpen.value=false;await openRun(r)}catch(e){error(e)}finally{busy.value=false}}
async function loadSettings(){settings.value=await api('/settings');if(hasRole('admin')){const [m,a,p]=await Promise.all([api('/members'),api('/audit'),api('/policies')]);members.value=m.items;memberCursor.value=m.next_cursor;auditCursor.value=a.next_cursor;audits.value=a.items.sort((a:any,b:any)=>b.created_at.localeCompare(a.created_at));policies.value=p.items}}
async function loadCatalogs(append=false){const r=await api('/catalogs?'+new URLSearchParams({q:catalogQuery.value,...(append&&catalogCursor.value?{cursor:catalogCursor.value}:{})}));catalogs.value=append?[...catalogs.value,...r.items]:r.items;catalogCursor.value=r.next_cursor}
async function loadBatches(append=false){const r=await api('/batches?'+new URLSearchParams({q:batchQuery.value,...(append&&batchCursor.value?{cursor:batchCursor.value}:{})}));batches.value=append?[...batches.value,...r.items]:r.items;batchCursor.value=r.next_cursor}
async function loadMembers(append=false){const r=await api('/members?'+new URLSearchParams({q:memberQuery.value,...(append&&memberCursor.value?{cursor:memberCursor.value}:{})}));members.value=append?[...members.value,...r.items]:r.items;memberCursor.value=r.next_cursor}
async function moreAudit(){const r=await api('/audit?cursor='+auditCursor.value);audits.value.push(...r.items);auditCursor.value=r.next_cursor}
async function saveSettings(){try{await put('/settings',{dual_review:settings.value.dual_review,default_policy_id:settings.value.default_policy_id});ElMessage.success('设置已保存，对之后创建的运行生效');await loadSettings()}catch(e){error(e)}}
async function addMember(){try{await post('/members',memberForm.value);memberOpen.value=false;memberForm.value={email:'',name:'',password:'',roles:['operator']};await loadSettings();ElMessage.success('成员已创建')}catch(e){error(e)}}
async function toggleMember(m:any){try{await put('/members/'+m.id,{roles:m.roles,active:!m.active});await loadSettings();ElMessage.success('成员状态已更新')}catch(e){error(e)}}
async function saveRoles(m:any){try{await put('/members/'+m.id,{roles:m.roles,active:m.active});ElMessage.success('角色已保存')}catch(e){error(e);await loadSettings()}}
async function addPolicy(){try{await post('/policies',policyForm.value);policyOpen.value=false;await loadSettings();ElMessage.success('已创建独立策略版本')}catch(e){error(e)}}
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{try{await restore();await loadMemberships();await load()}catch{}finally{booting.value=false}timer=setInterval(async()=>{if(!session.user||document.hidden)return;try{if(nav.value==='tasks'&&runs.value.some(r=>['RUNNING','QUEUED','CANCEL_REQUESTED'].includes(r.status)))await load();if(nav.value==='exports'&&exports.value.some(e=>['RUNNING','QUEUED'].includes(e.status)))await loadExports()}catch{}},3000)})
onUnmounted(()=>clearInterval(timer))
</script>

<template>
  <div v-if="booting" class="boot"><div class="brand-mark"><Boxes :size="24"/></div><p>正在打开工作空间…</p></div>
  <div v-else-if="!session.user" class="login-layout">
    <section class="login-story"><div class="brand"><span class="brand-mark"><Boxes :size="24"/></span><b>序同 <small>商品数据匹配平台</small></b></div><div class="login-copy"><span class="eyebrow">PRODUCT DATA, CONNECTED.</span><h1>让每一件商品，<br>都有清晰的对应。</h1><p>从供应商表格到企业标准库，<br>有依据地匹配，有记录地确认。</p><div class="flow-demo"><div><FileSpreadsheet/><span>供应商商品表</span><small>保留原始数据</small></div><ChevronRight/><div class="accent"><Sparkles/><span>匹配与核对</span><small>型号 · 规格 · 差异</small></div><ChevronRight/><div><CheckCheck/><span>确认映射</span><small>人工审核 · 可追溯</small></div></div></div><div class="login-foot"><ShieldCheck :size="16"/> 组织数据隔离 <span>·</span> 全流程版本留痕</div></section>
    <section class="login-panel"><div class="login-box"><span class="eyebrow">欢迎回来</span><h2>登录工作空间</h2><p class="muted">继续处理你的商品匹配任务</p><form @submit.prevent="login"><label>账号</label><el-input v-model="email" size="large" autocomplete="username" aria-label="账号"/><label>密码</label><el-input v-model="password" type="password" show-password size="large" autocomplete="current-password" aria-label="密码"/><el-button type="primary" size="large" native-type="submit" :loading="busy" class="full">登录工作空间 <ArrowUpRight :size="16"/></el-button></form><div class="demo-accounts"><span>演示账号 <small>使用构造商品数据</small></span><div class="account-options"><button v-for="(title,role) in {operator:'数据专员',reviewer:'审核员',admin:'管理员'}" :key="role" @click="email=role+'@demo.local';password='Demo2026!match'" :class="{selected:email.startsWith(role)}">{{ title }}</button></div><p>默认开启双人复核。请使用审核员账号确认数据专员提交的商品。</p></div></div></section>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="brand"><span class="brand-mark"><Boxes :size="23"/></span><b>序同<small>商品数据匹配平台</small></b></div><div class="workspace-switch"><span class="workspace-avatar">星</span><div><strong>{{ orgName.split(' · ')[0] }}</strong><small>团队工作空间</small></div><ChevronDown :size="14"/></div><span class="nav-caption">工作空间</span><nav><button aria-label="匹配任务" @click="navigate('tasks')" :class="{active:nav==='tasks'||nav==='workbench'}"><LayoutDashboard :size="18"/><span>匹配任务</span><span class="nav-count" v-if="pending">{{ pending }}</span></button><button aria-label="标准商品库" @click="navigate('catalog')" :class="{active:nav==='catalog'}"><Boxes :size="18"/><span>标准商品库</span></button><button aria-label="发布与协作" @click="enterpriseBatch='';navigate('enterprise')" :class="{active:nav==='enterprise'}"><ClipboardCheck :size="18"/><span>发布与协作</span></button><button aria-label="导出记录" @click="navigate('exports')" :class="{active:nav==='exports'}"><Download :size="18"/><span>导出记录</span></button><div class="nav-divider"></div><button aria-label="组织设置" @click="navigate('settings')" :class="{active:nav==='settings'}"><Settings2 :size="18"/><span>组织设置</span></button></nav><div class="sidebar-bottom"><div class="assurance"><ShieldCheck :size="17"/><span>每一次确认，都有据可查</span></div><div class="profile"><span class="profile-avatar">{{ session.user.name[0] }}</span><div><strong>{{ session.user.name.split(' · ')[0] }}</strong><small>{{ roles }}</small></div><button class="icon-button" title="退出并切换账号" @click="logout"><LogOut :size="16"/></button></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空间 <ChevronRight :size="14"/><span>{{ titles[nav] }}</span></div><div class="topbar-right"><span class="env-badge"><i></i> 本地工作空间</span><a href="/api/v1/docs" target="_blank" title="查看接口文档" class="icon-button"><CircleHelp :size="18"/></a></div></header>
      <Workbench v-if="nav==='workbench'&&activeRun" :key="activeRun.id" :run-id="activeRun.id" :initial-item="activeRun.initial_item_id" @release="(id:string)=>{enterpriseBatch=id;nav='enterprise'}" @open="openRun" @back="navigate('tasks')" @export="showExport" @revise="(id:string)=>startImport('batch',id)"/>
      <main v-else class="page-content"><EnterpriseHub v-if="nav==='enterprise'" :key="session.org+enterpriseBatch" :initial-batch="enterpriseBatch" @open="openRun"/>
        <template v-if="nav==='tasks'">
          <div class="page-heading"><div><div class="heading-kicker">工作概览</div><h1>匹配任务</h1><p>导入商品、核对差异，让每一条映射准确落地。</p></div><div class="button-row" v-if="hasRole('operator','admin')"><el-button @click="showRerun"><RefreshCw :size="15"/>新建运行版本</el-button><el-button type="primary" @click="startImport()"><Plus :size="17"/>新建匹配任务</el-button></div></div>
          <div class="stats-grid"><div class="stat-card"><span>全部匹配任务 <span class="stat-icon blue"><FolderOpen :size="18"/></span></span><strong>{{ totalRuns }}</strong><small>独立记录每一次匹配运行</small></div><div class="stat-card"><span>等待人工处理 <span class="stat-icon amber"><ClipboardCheck :size="18"/></span></span><strong>{{ pending }} <em>条</em></strong><small><i class="dot amber"></i> 匹配完成后，需要人工确认</small></div><div class="stat-card"><span>已确认映射 <span class="stat-icon green"><CheckCheck :size="18"/></span></span><strong>{{ dashboard.decisions?.CONFIRMED||0 }} <em>条</em></strong><small><i class="dot green"></i> 当前有效，可生成结果文件</small></div><div class="stat-card"><span>标准商品 <span class="stat-icon violet"><Boxes :size="18"/></span></span><strong>{{ dashboard.catalog_products||0 }} <em>件</em></strong><small>所有标准库版本内的商品记录</small></div></div>
          <div class="workflow-banner"><div class="banner-icon"><Sparkles :size="21"/></div><div><strong>从表格到映射，清晰走完每一步</strong><span>规格冲突与信息不足会单独标记，正式结果由审核员确认。</span></div><div class="mini-flow"><span>导入数据</span><ChevronRight :size="14"/><span>匹配核对</span><ChevronRight :size="14"/><span>确认导出</span></div></div>
          <section class="panel"><div class="panel-header"><div class="tab-strip"><button :class="{selected:!status}" @click="status='';loadRuns()">全部任务 <span>{{ totalRuns }}</span></button><button :class="{selected:status==='RUNNING'}" @click="status='RUNNING';loadRuns()">处理中</button><button :class="{selected:status==='SUCCEEDED'}" @click="status='SUCCEEDED';loadRuns()">已完成</button></div><div class="table-tools"><el-input v-model="query" placeholder="搜索任务或供应商" clearable @keyup.enter="loadRuns()" @clear="loadRuns()"><template #prefix><Search :size="15"/></template></el-input><button class="icon-button bordered" title="刷新任务" @click="load"><RefreshCw :size="16"/></button></div></div>
          <div class="table-scroll"><table class="data-table task-table"><thead><tr><th>任务名称 / 供应商</th><th>运行状态</th><th>匹配进度</th><th>待处理记录</th><th>创建时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td><div class="file-cell"><span class="file-icon"><FileSpreadsheet :size="20"/></span><div><button class="name-link" @click="openRun(r)">{{ r.batch_name }}</button><small>{{ r.supplier }} <span>·</span> 输入 v{{ r.revision_number }}</small></div></div></td><td><span class="status-pill" :class="r.status"><i></i>{{ labels[r.status] }}</span><small class="cell-sub" v-if="r.status==='SUCCEEDED'">{{ r.decisions.CONFIRMED||0 }} 条已确认</small></td><td><div class="progress-caption"><span>{{ r.processed }} <small>/ {{ r.total }}</small></span><small>{{ progress(r) }}%</small></div><div class="progress-track"><i :style="{width:progress(r)+'%'}"></i></div><small class="cell-sub" v-if="r.excluded">已排除 {{ r.excluded }} 条错误行</small></td><td><span class="review-number">{{ r.decisions.PENDING||0 }} <small>条</small></span><small class="cell-sub conflict-text" v-if="r.suggestions.CONFLICT">{{ r.suggestions.CONFLICT }} 条规格冲突</small></td><td><span class="time-cell">{{ date(r.created_at) }}</span><small class="cell-sub">{{ r.creator_name.split(' · ')[0] }}</small></td><td class="align-right"><button class="text-button" @click="openRun(r)">{{ r.status==='SUCCEEDED'?'进入工作台':'查看进度' }} <ChevronRight :size="14"/></button><div class="row-secondary"><button v-if="['RUNNING','QUEUED'].includes(r.status)&&hasRole('operator','admin')" @click="cancelRun(r)">取消</button><button v-if="['FAILED','CANCELLED'].includes(r.status)&&hasRole('operator','admin')" @click="retryRun(r)">重新运行</button><button v-if="r.status==='SUCCEEDED'" @click="showExport(r)">导出</button></div></td></tr></tbody></table></div><el-empty v-if="!runs.length" description="暂无匹配任务，导入第一份商品表开始核对"/><div class="table-footer"><span>已显示 {{ runs.length }} 个运行 · 计算完成不代表审核完成</span><el-button v-if="runCursor" size="small" @click="loadRuns(true)">加载更多</el-button></div></section>
          <div class="bottom-note"><ShieldCheck :size="15"/>商品原文、匹配依据和审核历史均独立保留，支持追溯到原始行。</div>
        </template>
        <template v-if="nav==='catalog'"><div class="page-heading"><div><div class="heading-kicker">统一商品身份</div><h1>标准商品库</h1><p>以已发布的标准库版本为依据，准确核对每一个销售 SKU。</p></div><el-button v-if="hasRole('admin','operator')" type="primary" @click="startImport('catalog')"><Plus :size="16"/>导入标准库</el-button></div><div class="catalog-layout"><aside class="panel catalog-list"><div class="section-title">商品库与版本</div><el-input v-model="catalogQuery" placeholder="搜索商品库" clearable @keyup.enter="loadCatalogs()" @clear="loadCatalogs()"/><div v-for="cat in catalogs" :key="cat.id" class="catalog-group"><strong><Boxes :size="17"/>{{ cat.name }}</strong><button v-for="v in cat.versions" :key="v.id" :class="{chosen:selectedCatalog===v.id}" @click="selectedCatalog=v.id;loadProducts()"><span>版本 {{ v.number }}<small>{{ v.row_count }} 件商品</small></span><span class="status-pill" :class="v.status">{{ labels[v.status] }}</span></button><div v-for="v in cat.versions.filter((x:any)=>x.status==='DRAFT')" :key="v.id" class="publish-line"><el-button v-if="hasRole('admin')" size="small" type="primary" plain @click="publish(v)">发布 v{{ v.number }}</el-button></div><button class="text-button" v-if="hasRole('admin','operator')" @click="startImport('catalog','',cat.id)"><Plus :size="14"/>导入新版本</button></div><el-button v-if="catalogCursor" @click="loadCatalogs(true)">更多商品库</el-button></aside><section class="panel grow"><div class="panel-header"><h3>商品明细</h3><el-input v-model="productQuery" placeholder="搜索名称、型号或编号" class="search-input" clearable @keyup.enter="loadProducts()" @clear="loadProducts()"><template #prefix><Search :size="15"/></template></el-input></div><div class="table-scroll"><table class="data-table"><thead><tr><th>内部编号</th><th>标准商品</th><th>规格</th><th>销售版本</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td class="mono">{{ p.sku }}</td><td><strong>{{ p.normalized.name }}</strong><small class="cell-sub">{{ p.normalized.brand }} · {{ p.normalized.model }}</small></td><td>{{ p.normalized.ram||'—' }} / {{ p.normalized.storage||'—' }}<small class="cell-sub">{{ p.normalized.color||'颜色缺失' }} · {{ p.normalized.pack_count||'—' }} 件装</small></td><td>{{ p.normalized.region||'缺失' }}</td></tr></tbody></table></div><el-empty v-if="!products.length" description="此版本暂无可用商品，请查看导入校验结果"/><div class="table-footer"><span>编号按文本保留 · 已发布版本不可修改</span><el-button v-if="productCursor" size="small" @click="loadProducts(true)">加载更多</el-button></div></section></div></template>
        <template v-if="nav==='exports'"><div class="page-heading"><div><div class="heading-kicker">文件与交付</div><h1>导出记录</h1><p>每份文件绑定生成时的审核快照，后续修改会显示历史提示。</p></div><el-button @click="loadExports()"><RefreshCw :size="15"/>刷新记录</el-button></div><section class="panel"><table class="data-table"><thead><tr><th>导出文件</th><th>范围 / 条数</th><th>快照状态</th><th>生成时间</th><th>到期时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="e in exports" :key="e.id"><td><div class="file-cell"><span class="file-icon"><FileSpreadsheet :size="19"/></span><div><strong>商品匹配结果.{{ e.format }}</strong><small>运行 {{ e.run_id.slice(0,8) }}</small></div></div></td><td>{{ e.kind==='confirmed'?'已确认映射':'全量状态报告' }}<small class="cell-sub">{{ e.count }} 条记录</small></td><td><span class="status-pill" :class="e.stale?'REVIEW':e.status">{{ e.stale?'历史快照 · 决定已变化':labels[e.status] }}</span><small class="cell-sub" v-if="e.stale">{{ e.changed_decisions }} 条决定已更新</small><small class="cell-sub" v-if="e.error">{{ e.error }}</small></td><td>{{ date(e.created_at) }}<small class="cell-sub">{{ e.creator_name.split(' · ')[0] }}</small></td><td>{{ date(new Date(e.expires_at*1000).toISOString()) }}</td><td class="align-right"><el-button v-if="e.status==='SUCCEEDED'" size="small" @click="download(e)"><Download :size="14"/>下载文件</el-button></td></tr></tbody></table><el-empty v-if="!exports.length" description="暂无导出记录，在匹配工作台生成第一份结果文件"/><div class="table-footer"><span>文件保留 30 天 · 已下载的旧文件不会自动更新</span><el-button v-if="exportCursor" size="small" @click="loadExports(true)">加载更多</el-button></div></section></template>
        <template v-if="nav==='settings'"><div class="page-heading"><div><div class="heading-kicker">团队与规则</div><h1>组织设置</h1><p>维护成员权限和之后运行使用的复核策略。</p></div></div><el-alert v-if="!hasRole('admin')" title="组织设置由管理员维护" type="info" :closable="false"/><template v-else><div class="settings-tabs"><button v-for="(label,id) in {members:'成员管理',policies:'匹配与复核',audit:'操作记录',experiments:'策略评测',operations:'运行状态'}" :class="{selected:settingsTab===id}" @click="settingsTab=id">{{ label }}</button></div><OperationsPanel v-if="settingsTab==='operations'"/><StrategyLab v-if="settingsTab==='experiments'" @changed="loadSettings"/><section v-if="settingsTab==='members'" class="panel"><div class="panel-header"><h3>组织成员 <small>{{ members.length }} 位</small></h3><el-input v-model="memberQuery" placeholder="搜索姓名或账号" class="search-input" clearable @keyup.enter="loadMembers()" @clear="loadMembers()"/><el-button type="primary" @click="memberOpen=true"><Plus :size="15"/>添加成员</el-button></div><table class="data-table"><thead><tr><th>成员</th><th>账号</th><th>角色权限</th><th>状态</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td><strong>{{ m.name }}</strong></td><td>{{ m.email }}</td><td><el-select v-model="m.roles" multiple style="width:260px" @change="saveRoles(m)"><el-option v-for="r in ['operator','reviewer','admin','viewer','publisher','supervisor','integration_manager','annotator','adjudicator']" :value="r" :label="labels[r]"/></el-select></td><td><span class="status-pill" :class="m.active?'SUCCEEDED':'CANCELLED'">{{ m.active?'正常':'已停用' }}</span></td><td class="align-right"><button class="text-button" @click="toggleMember(m)">{{ m.active?'停用':'启用' }}</button></td></tr></tbody></table><div class="table-footer"><el-button v-if="memberCursor" @click="loadMembers(true)">更多成员</el-button></div></section><div v-if="settingsTab==='policies'" class="settings-grid"><section class="panel settings-card"><h3><ShieldCheck :size="19"/>复核策略</h3><div class="setting-row"><div><strong>开启双人复核</strong><p>任务和输入的提交者不能审核自己的批次，管理员也遵循此规则。</p></div><el-switch v-model="settings.dual_review"/></div><label>默认匹配方案</label><el-select v-model="settings.default_policy_id" class="full"><el-option v-for="p in policies" :value="p.id" :label="p.name"/></el-select><p class="muted">更改仅对之后创建的运行生效，历史运行保留原方案。</p><el-button type="primary" @click="saveSettings">保存设置</el-button></section><section class="panel settings-card"><div class="section-title"><h3>匹配方案版本</h3><el-button size="small" @click="policyOpen=true"><Plus :size="14"/>新建方案</el-button></div><div class="policy-item" v-for="p in policies"><strong>{{ p.name }}</strong><span>{{ p.config.engine==='rules'?'规则基线':'学习模型' }} · {{ date(p.created_at) }}</span><small>{{ p.config.validated?'已通过准入评测':'探索性策略 · 正式映射仍需人工确认' }}</small></div></section></div><section v-if="settingsTab==='audit'" class="panel"><div class="panel-header"><h3>操作留痕</h3><el-button size="small" @click="loadSettings">刷新</el-button></div><table class="data-table"><thead><tr><th>操作</th><th>操作人</th><th>资源编号</th><th>时间</th></tr></thead><tbody><tr v-for="a in audits"><td class="mono">{{ a.action }}</td><td>{{ a.actor_name }}</td><td class="mono">{{ a.resource_id.slice(0,8) }}</td><td>{{ date(a.created_at) }}</td></tr></tbody></table><div class="table-footer">已加载 {{ audits.length }} 条操作记录<el-button v-if="auditCursor" @click="moreAudit">加载更多操作记录</el-button></div></section></template></template>
      </main>
    </div>
    <el-dialog v-model="importOpen" :title="importMode==='catalog'?'导入标准商品库':revisionBatch?'创建修正版输入':'新建匹配任务'" width="900px" destroy-on-close :close-on-click-modal="false"><ImportWizard :mode="importMode" :batch-id="revisionBatch" :catalog-id="catalogParent" :catalogs="published" :policies="policies" @complete="imported" @cancel="importOpen=false"/></el-dialog>
    <el-dialog v-model="exportOpen" title="生成结果文件" width="530px"><div class="dialog-summary"><FileSpreadsheet :size="25"/><div><strong>{{ exportRun?.batch_name }}</strong><small>本次将冻结生成时的审核结果</small></div></div><label>导出范围</label><el-radio-group v-model="exportKind"><el-radio-button value="confirmed">已确认映射</el-radio-button><el-radio-button value="all">全量状态报告</el-radio-button></el-radio-group><div class="export-count"><strong>{{ exportCount }}</strong> 条记录<small v-if="exportKind==='all'">未处理 {{ exportRun?.decisions?.PENDING||0 }} · 已确认 {{ exportRun?.decisions?.CONFIRMED||0 }} · 待补充 {{ exportRun?.decisions?.NEEDS_INFO||0 }} · 未匹配 {{ exportRun?.decisions?.UNMATCHED||0 }} · 已撤销 {{ exportRun?.decisions?.REVOKED||0 }}</small></div><label>文件格式</label><el-radio-group v-model="exportFormat"><el-radio value="xlsx">Excel (.xlsx)</el-radio><el-radio value="csv">CSV (.csv)</el-radio></el-radio-group><div class="mt16"><el-checkbox v-model="includeRaw">保留所有原始列</el-checkbox></div><template #footer><el-button @click="exportOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="createExport">确认生成 {{ exportCount }} 条记录</el-button></template></el-dialog>
    <el-dialog v-model="rerunOpen" title="新建运行版本" width="570px"><p class="muted">选择已有输入、标准库和匹配方案，生成独立运行。</p><label>供应商批次</label><div class="button-row"><el-input v-model="batchQuery" placeholder="搜索历史批次 / 供应商" clearable @keyup.enter="loadBatches()" @clear="loadBatches()"/><el-button @click="loadBatches()">搜索</el-button></div><el-select v-model="rerunBatch" class="full" @change="rerunRevision=rerunRevisions[0]?.id||''"><el-option v-for="b in batches" :value="b.id" :label="b.name"/></el-select><el-button v-if="batchCursor" size="small" @click="loadBatches(true)">更多历史批次</el-button><label>输入版本</label><el-select v-model="rerunRevision" class="full"><el-option v-for="r in rerunRevisions" :value="r.id" :label="`v${r.number} · ${r.valid} 条有效记录`"/></el-select><label>标准库版本</label><el-select v-model="rerunCatalog" class="full"><el-option v-for="v in published" :value="v.id" :label="v.label"/></el-select><label>匹配方案</label><el-select v-model="rerunPolicy" class="full"><el-option v-for="p in policies" :value="p.id" :label="p.name"/></el-select><template #footer><el-button @click="rerunOpen=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!rerunRevision||!rerunCatalog" @click="submitRerun">创建并运行</el-button></template></el-dialog>
    <el-dialog v-model="memberOpen" title="添加组织成员" width="500px"><label>姓名</label><el-input v-model="memberForm.name"/><label>账号邮箱</label><el-input v-model="memberForm.email"/><label>初始密码（至少 10 位）</label><el-input v-model="memberForm.password" type="password" show-password/><label>角色</label><el-select v-model="memberForm.roles" multiple class="full"><el-option v-for="r in ['operator','reviewer','admin','viewer','publisher','supervisor','integration_manager','annotator','adjudicator']" :value="r" :label="labels[r]"/></el-select><template #footer><el-button @click="memberOpen=false">取消</el-button><el-button type="primary" @click="addMember">创建成员</el-button></template></el-dialog>
    <el-dialog v-model="policyOpen" title="新建匹配方案版本" width="500px"><el-alert title="规则阈值需要独立评测。修改不会自动确认商品。" type="info" :closable="false"/><label>方案名称</label><el-input v-model="policyForm.name"/><label>推荐阈值</label><el-input-number v-model="policyForm.high_threshold" :min="0" :max="1" :step="0.01"/><label>首选与次选分差</label><el-input-number v-model="policyForm.margin" :min="0" :max="1" :step="0.01"/><template #footer><el-button @click="policyOpen=false">取消</el-button><el-button type="primary" @click="addPolicy">创建版本</el-button></template></el-dialog>
  </div>
</template>
